import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    strings = data[1:1+n]

    pos = {}
    neg = {}

    for s in strings:
        bal = 0
        min_bal = 0
        for ch in s:
            if ch == 40:  # '('
                bal += 1
            else:
                bal -= 1
            if bal < min_bal:
                min_bal = bal

        if min_bal >= 0:
            pos[bal] = pos.get(bal, 0) + 1
        else:
            bal2 = 0
            min_bal2 = 0
            for ch in reversed(s):
                if ch == 41:  # ')'
                    bal2 += 1
                else:
                    bal2 -= 1
                if bal2 < min_bal2:
                    min_bal2 = bal2
            if min_bal2 >= 0:
                need = bal2
                neg[need] = neg.get(need, 0) + 1

    ans = 0
    for b, cnt in pos.items():
        if b in neg:
            ans += min(cnt, neg[b])

    print(ans)

if __name__ == "__main__":
    solve()
